import numpy as np

def calculate_stats_for_students(test_results):
    """
    Calculate the average test score and the standard deviation for each student.

    Parameters:
        test_results (list of dict): Each dict contains a student ID and that
            student's test score(s). Recognized keys are 'student_id'/'student'/'id'
            for the student identifier and 'score'/'scores'/'test_score' for the
            score(s). A score may be a single number or a list of numbers.

    Returns:
        dict: Keys are student IDs, values are tuples
              (average_score, standard_deviation).

    Raises:
        ValueError: If a student in test_results does not have any test scores.
    """
    id_keys = ('student_id', 'student', 'id')
    score_keys = ('scores', 'score', 'test_score', 'test_scores')

    def _lookup(record, keys):
        for k in keys:
            if k in record:
                return record[k]
        return None

    scores_by_student = {}

    for record in test_results:
        if not isinstance(record, dict):
            raise ValueError("Each test result must be a dictionary.")
        sid = _lookup(record, id_keys)
        if sid is None:
            raise ValueError("Test result is missing a student ID.")
        value = _lookup(record, score_keys)

        if sid not in scores_by_student:
            scores_by_student[sid] = []

        if value is None:
            continue

        if isinstance(value, (list, tuple, np.ndarray, pd.Series)):
            vals = list(value)
        else:
            vals = [value]
        scores_by_student[sid].extend(
            v for v in vals if v is not None and not (isinstance(v, float) and np.isnan(v))
        )

    result = {}
    for sid, scores in scores_by_student.items():
        if len(scores) == 0:
            raise ValueError(f"Student {sid} does not have any test scores.")
        arr = np.asarray(scores, dtype=float)
        avg = float(np.mean(arr))
        std = float(np.std(arr, ddof=1)) if arr.size > 1 else 0.0
        result[sid] = (avg, std)
    return result


